#include  "sparc.H"
#include  "sparc_isa.cpp"

#include  "sparc_syscall.H"

void* sparc::dispatch() {
  if( ac_pc >= dec_cache_size){
    cerr << "ArchC: Address out of bounds (pc=0x" << hex << ac_pc << ")." << endl;
    stop();
    longjmp(ac_env, AC_ACTION_STOP);
  }
  ac_instr_counter++;
  unsigned ins_id;
  instr_dec = (DEC_CACHE + (ac_pc / 4));
  if ( !instr_dec->valid ){
    unsigned* ins_cache;
    decode_pc = ac_pc;
    quant = 0;
    ins_cache = (ISA.decoder)->Decode(reinterpret_cast<unsigned char*>(buffer), quant);
    instr_dec->valid = true;
    instr_dec->id = ins_cache ? ins_cache[IDENT]: 0;
    instr_dec->end_rot = IntRoutine[instr_dec->id];
    switch (ISA.instr_format_table[instr_dec->id]) {
      case 1:
        instr_dec->F_Type_F2.op = ins_cache[1];
        instr_dec->F_Type_F2.rd = ins_cache[2];
        instr_dec->F_Type_F2.op2 = ins_cache[3];
        instr_dec->F_Type_F2.imm22 = ins_cache[4];
      break;
      case 2:
        instr_dec->F_Type_F3R.op = ins_cache[1];
        instr_dec->F_Type_F3R.rd = ins_cache[2];
        instr_dec->F_Type_F3R.op3 = ins_cache[5];
        instr_dec->F_Type_F3R.rs1 = ins_cache[6];
        instr_dec->F_Type_F3R.i = ins_cache[7];
        instr_dec->F_Type_F3R.asi = ins_cache[8];
        instr_dec->F_Type_F3R.rs2 = ins_cache[9];
      break;
      case 3:
        instr_dec->F_Type_F3I.op = ins_cache[1];
        instr_dec->F_Type_F3I.rd = ins_cache[2];
        instr_dec->F_Type_F3I.op3 = ins_cache[5];
        instr_dec->F_Type_F3I.rs1 = ins_cache[6];
        instr_dec->F_Type_F3I.i = ins_cache[7];
        instr_dec->F_Type_F3I.simm13 = ins_cache[10];
      break;
      case 4:
        instr_dec->F_Type_BR.op = ins_cache[1];
        instr_dec->F_Type_BR.a = ins_cache[11];
        instr_dec->F_Type_BR.cond = ins_cache[12];
        instr_dec->F_Type_BR.op2 = ins_cache[3];
        instr_dec->F_Type_BR.disp22 = ins_cache[13];
      break;
      case 5:
        instr_dec->F_Type_HLT.op = ins_cache[1];
        instr_dec->F_Type_HLT.rd = ins_cache[2];
        instr_dec->F_Type_HLT.op3 = ins_cache[5];
        instr_dec->F_Type_HLT.imm = ins_cache[14];
      break;
      default:
        cerr << "ArchC Error: Unidentified instruction. " << endl;
        cerr << "PC = " << hex << ac_pc << dec << endl;
        stop();
        longjmp(ac_env, AC_ACTION_STOP);
    }
  }
  ins_id = instr_dec->id;

  return instr_dec->end_rot;
}

